#!/usr/bin/env node
// node cli.mjs people.json START DAYS [earlier-rota.json ...]
// Earlier rotas (this program's own output) are optional. Given them, the new rota leans toward
// whoever is owed shifts or weekends from those periods, still inside the policy's bounds.
import { readFileSync } from 'node:fs';
import { loadPeople } from './lib/people.mjs';
import { makeRota, ledger } from './lib/assign.mjs';

const [file, start, n, ...earlier] = process.argv.slice(2);
try {
  const people = loadPeople(file);
  const carry = ledger(people, earlier.map((f) => JSON.parse(readFileSync(f, 'utf8'))));
  console.log(JSON.stringify(makeRota(people, start, Number(n), { carry })));
} catch (e) {
  console.error(`rota: ${e.message}`);
  process.exit(1);
}

