// assign.mjs — who works when, under POLICY.md.
//
// Every rule in POLICY.md is a hard constraint here. The rota is found by depth-first search,
// day by day, trying first the pairs that are furthest behind their fair share. Pruning keeps
// every partial rota able to finish inside every person's bounds. If no rota exists, or the
// search gives up, it throws: it never quietly relaxes a rule.
import { days as periodDays, isWeekend } from './calendar.mjs';

export const MAX_RUN = 5; // rule 3
export const TOTAL_TOL = 2; // rule 4
export const WEEKEND_TOL = 1.5; // rule 5
const EPS = 1e-9;
// Restart jitter, added to pair scores after the first attempt. Scores differ by a few shifts,
// so 12 is close to a random order: restarts explore genuinely different early choices. With
// 0.6 the search gave up on a feasible team (test-hard-teams.json, first entry) after 2M nodes;
// with 12 it finds it in ~40 ms. On 1000 random teams (scratch-why.mjs seed 1) both scales
// solve the same 784. Attempt 0 is unjittered, so ordinary teams get the same rota as before.
const JITTER = 12;

// Fair shares as the policy defines them (rules 4 and 5). Exported so tests and callers can
// show people their own numbers.
export function fairShares(people, start, n) {
  const ds = periodDays(start, n);
  const weekendDays = ds.filter(isWeekend).length;
  const weights = people.map((p) => (p.fte * ds.filter((d) => !p.leave.has(d)).length) / n);
  const total = weights.reduce((a, b) => a + b, 0);
  return people.map((p, i) => ({
    name: p.name,
    weight: weights[i],
    shifts: total > 0 ? (2 * n * weights[i]) / total : 0,
    weekendShifts: total > 0 ? (2 * weekendDays * weights[i]) / total : 0,
  }));
}

// Each person's surplus (worked minus fair share, shifts and weekend shifts) summed over earlier
// rotas, judged by the policy's own shares for each of those periods. People who don't appear
// in an earlier rota are left out of that rota's sums (they weren't on the team, or worked
// nothing; the file can't say which). Leave is taken from the current team file, so keep past
// leave dates in it for the sums to be exact.
export function ledger(people, rotas) {
  const carry = Object.fromEntries(people.map((p) => [p.name, { shifts: 0, weekendShifts: 0 }]));
  for (const rota of rotas) {
    const ds = Object.keys(rota).sort();
    if (!ds.length) continue;
    const present = new Set(Object.values(rota).flat());
    const team = people.filter((p) => present.has(p.name));
    if (team.length < 2) continue;
    for (const s of fairShares(team, ds[0], ds.length)) {
      const on = ds.filter((d) => rota[d].includes(s.name));
      carry[s.name].shifts += on.length - s.shifts;
      carry[s.name].weekendShifts += on.filter(isWeekend).length - s.weekendShifts;
    }
