// Does the alphabetical tie-break survive at the margin? Run 13 consecutive 28-day rotas and sum
// each person's (shifts - share) and (weekend shifts - weekend share).
import { loadPeople, validatePeople } from './lib/people.mjs';
import { makeRota, fairShares } from './lib/assign.mjs';
import { days, isWeekend } from './lib/calendar.mjs';
const path = new URL('./people.json', import.meta.url).pathname;
const reverse = process.argv[2] === 'rev';
let ppl = loadPeople(path);
if (reverse) ppl = ppl.reverse();
const tot = Object.fromEntries(ppl.map((p) => [p.name, [0, 0]]));
let start = '2026-11-02';
for (let k = 0; k < 13; k++) {
  const r = makeRota(ppl, start, 28);
  for (const s of fairShares(ppl, start, 28)) {
    const c = Object.entries(r).filter(([, v]) => v.includes(s.name));
    tot[s.name][0] += c.length - s.shifts;
