// Modulo: in scratch-case.json nurse caps sum to exactly n, so every day has exactly one nurse
// and one aide, and the problem splits into two independent one-per-day schedules.
// This solves each half with rest-aware floor pruning.
import { readFileSync } from 'node:fs';
import { fairShares } from './lib/assign.mjs';
import { days, isWeekend } from './lib/calendar.mjs';
import { validatePeople } from './lib/people.mjs';
const c = JSON.parse(readFileSync('./scratch-case.json', 'utf8'));
const team = validatePeople(c.team), n = c.n, ds = days(c.start, n), wk = ds.map(isWeekend);
const sh = fairShares(team, c.start, n);
const halves = [];
const f = (x) => Math.floor(x + 1e-9), cl = (x) => Math.max(0, Math.ceil(x - 1e-9));
for (const role of ['nurse', 'aide']) {
  const N = team.map((p, i) => i).filter((i) => team[i].role === role);
  const hi = N.map((i) => f(sh[i].shifts + 2)), lo = N.map((i) => cl(sh[i].shifts - 2));
  const whi = N.map((i) => f(sh[i].weekendShifts + 1.5)), wlo = N.map((i) => cl(sh[i].weekendShifts - 1.5));
  const cnt = N.map(() => 0), wc = N.map(() => 0), run = N.map(() => 0), out = [];
  let nodes = 0;
  const capOK = (t) => {
    let need = 0, wneed = 0;
    const wl = wk.slice(t).filter(Boolean).length;
    for (let k = 0; k < N.length; k++) {
      let r = run[k], a = 0, rw = run[k], w = 0;
      for (let u = t; u < n; u++) {
        const L = team[N[k]].leave.has(ds[u]);
        if (!L && r < 5) { r++; a++; } else r = 0;
        if (wk[u] && !L && rw < 5) { rw++; w++; } else rw = 0;
      }
      if (cnt[k] + a < lo[k] || wc[k] + w < wlo[k]) return false;
      need += Math.max(0, lo[k] - cnt[k]); wneed += Math.max(0, wlo[k] - wc[k]);
    }
    return need <= n - t && wneed <= wl;
  };
  const rec = (t) => {
    if (++nodes > 5e6) throw new Error('budget');
    if (t === n) return true;
    const ord = N.map((_, k) => k).sort((a, b) => (lo[b] - cnt[b]) - (lo[a] - cnt[a]));
    for (const k of ord) {
      if (team[N[k]].leave.has(ds[t]) || run[k] >= 5 || cnt[k] >= hi[k] || (wk[t] && wc[k] >= whi[k])) continue;
      const sv = run.slice();
      for (let j = 0; j < N.length; j++) run[j] = j === k ? run[j] + 1 : 0;
      cnt[k]++; if (wk[t]) wc[k]++; out[t] = team[N[k]].name;
      if (capOK(t + 1) && rec(t + 1)) return true;
      cnt[k]--; if (wk[t]) wc[k]--;
      for (let j = 0; j < N.length; j++) run[j] = sv[j];
    }
    return false;
  };
  let res;
  try { res = rec(0); } catch (e) { res = e.message; }
  console.log(role, 'lo', lo, 'hi', hi, '→', res, 'nodes', nodes);
  if (res === true) console.log('  ', out.join(' '));
  halves.push(out.slice());
}
// Check the combined rota against the policy, independently of the solver.
const v = [];
const w = team.map((p) => (p.fte * ds.filter((d) => !p.leave.has(d)).length) / n), W = w.reduce((a, b) => a + b);
const wd = ds.filter(isWeekend).length;
team.forEach((p, i) => {
  let s = 0, tot = 0, wt = 0;
  ds.forEach((d, t) => {
    const on = halves.some((h) => h[t] === p.name);
    if (on && p.leave.has(d)) v.push(`leave ${p.name} ${d}`);
    s = on ? s + 1 : 0;
    if (s > 5) v.push(`rest ${p.name} ${d}`);
    if (on) { tot++; if (wk[t]) wt++; }
