const rand = rng(Number(process.argv[2] || 11));
const N = Number(process.argv[3] || 300);
const why = {};
const bump = (k) => { why[k] = (why[k] || 0) + 1; };
for (let k = 0; k < N; k++) {
  const size = 5 + Math.floor(rand() * 8);
  const n = [28, 30, 31, 91][Math.floor(rand() * 4)];
  const start = days('2026-01-01', 365)[Math.floor(rand() * 365)], ds = days(start, n);
  const team = validatePeople(Array.from({ length: size }, (_, i) => {
    const leave = [];
    if (rand() < 0.5) { const s = Math.floor(rand() * n), len = 1 + Math.floor(rand() * 10); for (let d = s; d < Math.min(n, s + len); d++) leave.push(ds[d]); }
    return { name: `P${i}`, role: i < 2 || rand() < 0.4 ? 'nurse' : 'aide', fte: [1, 1, 1, 0.8, 0.6, 0.5][Math.floor(rand() * 6)], leave };
  }));
