  if (ds.some((d) => { const f = team.filter((p) => !p.leave.has(d)); return f.length < 2 || !f.some((p) => p.role === 'nurse'); })) tags.push('short day');
  const wkFree = team.map((p) => ds.filter((d) => isWeekend(d) && !p.leave.has(d)).length);
  if (team.some((p, i) => wkFree[i] < Math.ceil(sh[i].weekendShifts - 1.5 - 1e-9))) tags.push('weekend floor > weekends available');
