  if (aideMin > n) tags.push('aide floors > days');
  const wd = ds.filter(isWeekend).length;
  const nurseWk = team.reduce((s, p, i) => s + (p.role === 'nurse' ? Math.min(wkFree[i], Math.floor(sh[i].weekendShifts + 1.5 + 1e-9)) : 0), 0);
  if (nurseWk < wd) tags.push('nurse weekend caps < weekend days');
