let bad = 0;
const ok = (name, cond, why = '') => { if (!cond) bad++; console.log(`${cond ? 'ok  ' : 'FAIL'} ${name}${cond || !why ? '' : ` — ${why}`}`); };
const throws = (fn, re) => { try { fn(); return false; } catch (e) { return re.test(e.message); } };

// An independent checker for POLICY.md. It does not use the solver's own share code, so a bug
// in the solver's arithmetic can't hide here. Returns a list of broken rules (empty = obeys).
function policyViolations(team, start, n, rota) {
  const v = [];
  const ds = days(start, n);
  const role = Object.fromEntries(team.map((p) => [p.name, p.role]));
  if (Object.keys(rota).join() !== ds.join()) v.push('rota does not cover exactly the period');
  for (const d of ds) {
    const on = rota[d] || [];
    if (on.length !== 2 || new Set(on).size !== 2 || !on.every((x) => x in role)) v.push(`1 cover: ${d} ${on}`);
    else if (!on.some((x) => role[x] === 'nurse')) v.push(`1 nurse: ${d}`);
  }
  for (const p of team) {
    let streak = 0;
    for (const d of ds) {
      const on = (rota[d] || []).includes(p.name);
      if (on && p.leave.has(d)) v.push(`2 leave: ${p.name} ${d}`);
      streak = on ? streak + 1 : 0;
      if (streak > 5) v.push(`3 rest: ${p.name} ${d}`);
    }
  }
  const w = team.map((p) => (p.fte * ds.filter((d) => !p.leave.has(d)).length) / n);
  const W = w.reduce((a, b) => a + b, 0);
  const wkDays = ds.filter(isWeekend);
  team.forEach((p, i) => {
    const total = ds.filter((d) => rota[d]?.includes(p.name)).length;
    const wk = wkDays.filter((d) => rota[d]?.includes(p.name)).length;
    const share = (2 * n * w[i]) / W, wshare = (2 * wkDays.length * w[i]) / W;
    if (Math.abs(total - share) > 2 + 1e-9) v.push(`4 fair share: ${p.name} ${total} vs ${share.toFixed(2)}`);
    if (Math.abs(wk - wshare) > 1.5 + 1e-9) v.push(`5 weekends: ${p.name} ${wk} vs ${wshare.toFixed(2)}`);
  });
  return v;
}
const obeys = (name, team, start, n) => {
  let rota, v;
  try { rota = makeRota(team, start, n); v = policyViolations(team, start, n, rota); } catch (e) { v = [`threw: ${e.message}`]; }
  ok(name, v.length === 0, v.slice(0, 3).join('; '));
  return rota;
};

// A small seeded RNG (mulberry32) so random teams are the same on every run. Integer maths via
// Math.imul: the previous LCG multiplied past 2^53, lost its low bits and cycled after ~10k
// draws, so only 142 of the "200" random teams below were distinct.
const rng = (a) => () => {
  a = (a + 0x6d2b79f5) | 0;
  let t = Math.imul(a ^ (a >>> 15), 1 | a);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};

