  const t = validatePeople([{ name: 'N1', role: 'nurse' }, { name: 'N2', role: 'nurse' }, { name: 'A', role: 'aide' }]);
  ok('window proof: a coverable team has no short window', shortWindow(t, days('2026-11-02', 14)) === null);
  ['2026-11-03', '2026-11-04', '2026-11-05', '2026-11-06', '2026-11-07'].forEach((d) => t[1].leave.add(d));
  ok('window proof: finds the short window', shortWindow(t, days('2026-11-02', 14)) === '2026-11-02..2026-11-07');
  // N1 and A are each forced only 5 days (11-03..07), so no single person's run exposes it;
  // but 11-02..07 needs 12 shifts and leave + rest allow 5 + 5 + 1.
  ok('short window: refuses and names the window', throws(() => makeRota(t, '2026-11-02', 14), /from 2026-11-02 to 2026-11-07 \(6 days\).*at most 11 shifts/));
}

